import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse(`{"title":"Should We Help an Elderly Stranger?","description":"A complete English translation of a 2016 personal essay about two encounters and the judgment to help within one's capacity.","frontmatter":{"title":"Should We Help an Elderly Stranger?","description":"A complete English translation of a 2016 personal essay about two encounters and the judgment to help within one's capacity.","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/archive/help-the-elderly.md","filePath":"en/threads/archive/help-the-elderly.md","lastUpdated":1788220800000}`),r={name:"en/threads/archive/help-the-elderly.md"};function l(i,e,s,d,h,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="should-we-help-an-elderly-stranger" tabindex="-1">Should We Help an Elderly Stranger? <a class="header-anchor" href="#should-we-help-an-elderly-stranger" aria-label="Permalink to &quot;Should We Help an Elderly Stranger?&quot;">​</a></h1><p><strong>Editor&#39;s note (2026-08-31):</strong> This is a personal account, not first-aid, legal, or risk-probability guidance. In a real emergency, protect both people, contact local emergency services or professionals, and do not generalise from the author&#39;s experience of not being accused.</p><blockquote><p>Original date: 2016-04-24. The original Wayback Machine snapshot now returns 404; this page preserves the repository&#39;s historical text and does not treat the dead address as reviewable evidence.</p></blockquote><p>This is a controversial question. I can only describe what I personally did.</p><h2 id="first-encounter" tabindex="-1">First Encounter <a class="header-anchor" href="#first-encounter" aria-label="Permalink to &quot;First Encounter&quot;">​</a></h2><p>On a visit home, I took my mother to a morning market. Outside a live-fish shop, we met an elderly man with a heavy nosebleed. I initially only pointed towards a hospital about six hundred metres away.</p><p>When he took his first step, he nearly fell. The ground around the fish shops was slippery, and tilting his head made an accident more likely. I caught up and supported him. At a crossing, a large truck passed while he moved forward in confusion and almost pulled us both towards it. He became frightened, asked me to save him, and collapsed trembling against me.</p><p>My mother carried his bag while I supported him quickly to the emergency department. In the lift I could feel his heartbeat. The moment affected me deeply.</p><p>The first response from a doctor was harsher than I expected, and I found myself reassuring the man. He was treated successfully and thanked us repeatedly before I left.</p><h2 id="second-encounter" tabindex="-1">Second Encounter <a class="header-anchor" href="#second-encounter" aria-label="Permalink to &quot;Second Encounter&quot;">​</a></h2><p>Several years earlier, I saw an older man fall on a bridge to a park and helped him up. He turned out to be begging. He did not accuse me of anything; instead, he thanked me and held my hand so that I could not easily leave.</p><p>To ease the awkward situation, I asked where he lived. He said he was from Anhui and had no money. He produced a wallet and identity card, but the card showed that he was local to my hometown. I showed him my own inexpensive wallet and joked that his branded one was better. We talked about why he begged and about his experiences.</p><p>Later, when an elderly woman asked me for money, I talked with her about family and the difficulty of life, bought her a milk tea, and explained that young people also struggled. When we met again, she would greet me warmly.</p><p>Neither encounter led to an accusation. That does not establish a general probability; it reports only my experience. My point was not moral superiority. We will also become old, and I hope people are not left unaided after a fall.</p><p>My simple conclusion was: assess the situation and help within your capacity. In an emergency, protect the person and yourself, call local emergency services, and avoid actions beyond your training.</p><h2 id="original-comment" tabindex="-1">Original Comment <a class="header-anchor" href="#original-comment" aria-label="Permalink to &quot;Original Comment&quot;">​</a></h2><p>A reader observed that willingness to help may differ by age and responsibilities. The author replied that circumstances matter while still advocating help.</p>',17)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
